// This file is generated by AI.

// 文本预处理选项卡的会话注册表: 会话 (NovelSession) 与 Monaco model 跨挂载存活。
//
// 选项卡切换时组件会卸载, 但会话状态 (步骤、文本、人物等) 与 model 保留在注册表中,
// 重新挂载时按 id 恢复, 避免「切走再切回后回到初始状态」。

import * as monaco from 'monaco-editor';

import { NovelSession, type IEditorHost } from 'webgal-novel-preprocess';

const sessions = new Map<string, NovelSession>();

export function novelModelUri(id: string): string {
  return `inmemory://novel-preprocess/${id}`;
}

/** 获取 (或创建) 该选项卡的会话, 并绑定到当前编辑器宿主。 */
export function getOrCreateSession(id: string, host: IEditorHost): NovelSession {
  let session = sessions.get(id);
  if (!session) {
    session = new NovelSession(host);
    sessions.set(id, session);
  } else {
    session.attach(host);
  }
  return session;
}

/** 选项卡切换时解绑宿主 (保留会话状态, 供重新挂载后恢复)。 */
export function releaseSession(id: string): void {
  sessions.get(id)?.detach();
}

/** 关闭选项卡: 销毁会话与对应 model。 */
export function disposeNovelTab(id: string): void {
  sessions.get(id)?.dispose();
  sessions.delete(id);
  const uri = monaco.Uri.parse(novelModelUri(id));
  monaco.editor.getModel(uri)?.dispose();
}

/** 关闭项目: 销毁全部文本预处理会话与 model。 */
export function disposeAllNovelTabs(): void {
  for (const id of [...sessions.keys()]) disposeNovelTab(id);
}
